// Allowed courses
const validCourses = [
  "Java",
  "Python",
  "Data Science",
  "Web Development",
  "Cloud Computing"
];

// Process all incoming items
return items.map((item) => {
  let rawData = item.json;

  // 1. If the input has a 'text' field containing a stringified JSON (from LLM Output)
  if (typeof rawData.text === "string") {
    try {
      rawData = JSON.parse(rawData.text);
    } catch (error) {
      return {
        json: {
          error: "Invalid JSON in text field",
          rawData: item.json.text
        }
      };
    }
  } 
  // 2. Fallback: If 'data' property is used
  else if (typeof rawData.data === "string") {
    try {
      rawData = JSON.parse(rawData.data);
    } catch (error) {
      return {
        json: {
          error: "Invalid JSON in data field",
          rawData: item.json.data
        }
      };
    }
  } 
  // 3. Fallback: If the entire item is a string
  else if (typeof rawData === "string") {
    try {
      rawData = JSON.parse(rawData);
    } catch (error) {
      return {
        json: {
          error: "Invalid JSON string",
          rawData: rawData
        }
      };
    }
  }

  // -------------------------
  // Clean individual fields
  // -------------------------

  const studentId = String(rawData.studentId || "").trim();

  const studentName = String(rawData.studentName || "")
    .trim()
    .replace(/\s+/g, " ");

  const email = String(rawData.email_id || "")
    .trim()
    .toLowerCase();

  const phone = String(rawData.PhoneNumber || "")
    .replace(/\D/g, "");

  const course = String(rawData.Course || "")
    .trim();

  const city = String(rawData.City || "")
    .trim();

  // Convert Fee_paid to true/false
  const feePaid =
    rawData.Fee_paid === true ||
    String(rawData.Fee_paid).toLowerCase() === "true";

  // -------------------------
  // Validation
  // -------------------------

  const emailValid =
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

  const phoneValid =
    /^\d{10}$/.test(phone);

  const courseValid =
    validCourses.includes(course);

  // -------------------------
  // Return cleaned record
  // -------------------------

  return {
    json: {
      studentId,
      studentName,
      email_id: email,
      PhoneNumber: phone,
      Course: courseValid ? course : "INVALID_COURSE",
      City: city,
      Fee_paid: feePaid,

      Email_valid: emailValid,
      Phone_valid: phoneValid,
      Course_valid: courseValid
    }
  };
});
